function SettingsRow({ title, desc, children }: { title: React.ReactNode; desc?: React.ReactNode; children?: React.ReactNode }) {
  return (
    <div style={{ display: 'flex', alignItems: 'flex-start', gap: 24, padding: '14px 0', borderTop: '1px solid var(--border)' }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div className="cjk t-body-lg" style={{ color: 'var(--fg-0)' }}>{title}</div>
        {desc ? <div className="cjk t-caption" style={{ color: 'var(--fg-2)', marginTop: 3, lineHeight: 1.55 }}>{desc}</div> : null}
      </div>
      <div style={{ flexShrink: 0 }}>{children}</div>
    </div>
  );
}

/**
 * A switch that really switches.
 *
 * It used to hold its own `useState` seeded from a prop and never report the
 * change anywhere, so "紧凑模式" and "减少动效" flipped for as long as the pane
 * stayed mounted and reverted on the next visit — a settings page that displayed
 * a value without applying it. State now lives in the preference store, and the
 * control only renders a switch when the value is one the client can actually
 * hold. `locked` renders a read-only value with a reason instead, for the
 * settings that live on the server or in the DLL.
 */
function ToggleS({ on, onChange, lockedReason }: {
  on: boolean;
  onChange?: (next: boolean) => void;
  lockedReason?: string;
}) {
  const track = (
    <span
      role="switch"
      aria-checked={on}
      tabIndex={lockedReason ? -1 : 0}
      onClick={() => { if (!lockedReason) onChange?.(!on); }}
      onKeyDown={(e) => {
        if (lockedReason) return;
        if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); onChange?.(!on); }
      }}
      style={{
        display: 'inline-block', width: 32, height: 18, borderRadius: 999,
        background: on ? 'var(--fg-1)' : 'var(--bg-3)',
        border: '1px solid var(--border)', position: 'relative',
        cursor: lockedReason ? 'not-allowed' : 'pointer',
        opacity: lockedReason ? 0.5 : 1,
        transition: 'background var(--duration-fast) var(--ease-out-quart)',
      }}
    >
      <span className="toggle-thumb" style={{
        position: 'absolute', top: 1, left: on ? 15 : 1, width: 14, height: 14,
        borderRadius: '50%', background: on ? 'var(--bg-0)' : 'var(--fg-2)',
      }} />
    </span>
  );
  return lockedReason ? <Unavailable reason={lockedReason}>{track}</Unavailable> : track;
}

function ThemeSwatch({ label, dark, active, onClick }: { label: string; dark: boolean; active?: boolean; onClick?: () => void }) {
  return (
    <div onClick={onClick} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, cursor: 'pointer' }}>
      <div style={{
        width: 88, height: 60, borderRadius: 8,
        background: dark ? '#0F0F10' : '#F8F7F4',
        border: `2px solid ${active ? 'var(--accent)' : 'var(--border)'}`,
        position: 'relative', overflow: 'hidden',
      }}>
        <div style={{ position: 'absolute', inset: 6, borderRadius: 4, background: dark ? '#1A1A1B' : '#FFFFFF', border: `1px solid ${dark ? '#2A2A2C' : '#EAE8E2'}` }}>
          <div style={{ position: 'absolute', top: 6, left: 6, right: 6, height: 5, background: dark ? '#27272A' : '#EAE8E2', borderRadius: 2 }} />
          <div style={{ position: 'absolute', top: 14, left: 6, width: 16, height: 26, background: dark ? '#27272A' : '#EAE8E2', borderRadius: 2 }} />
          <div style={{ position: 'absolute', top: 14, left: 26, right: 6, height: 4, background: dark ? '#3A3A3D' : '#D6D3CA', borderRadius: 1 }} />
          <div style={{ position: 'absolute', top: 22, left: 26, right: 12, height: 3, background: dark ? '#3A3A3D' : '#D6D3CA', borderRadius: 1 }} />
        </div>
      </div>
      <div className="cjk t-caption" style={{ fontWeight: active ? 700 : 500, color: active ? 'var(--fg-0)' : 'var(--fg-2)' }}>{label}</div>
    </div>
  );
}

/**
 * A font swatch that knows whether the font exists.
 *
 * These three were the clearest case of a control that looks live and does
 * nothing: no onClick on any of them, and `active` was a literal on the first.
 * The two non-default stacks name fonts that are not guaranteed to be installed,
 * and picking an absent font renders the same glyphs — a click that appears to
 * fail. `fontAvailable` asks the browser instead, so a missing font is shown
 * missing rather than accepted.
 */
function FontSwatch({ choice, active, onPick }: {
  choice: FontChoice;
  active: boolean;
  onPick: (choice: FontChoice) => void;
}) {
  const font = FONTS[choice];
  const available = isFontAvailable(font.family);

  const card = (
    <div style={{
      padding: 12, borderRadius: 'var(--r-md)',
      border: `1px solid ${active ? 'var(--border-strong)' : 'var(--border)'}`,
      background: active ? 'var(--bg-2)' : 'var(--bg-1)',
      cursor: available ? 'pointer' : 'not-allowed',
    }}>
      <div className="cjk" style={{ fontFamily: font.family, fontSize: 16, fontWeight: 600, color: 'var(--fg-0)' }}>{font.sample}</div>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 6, marginTop: 6 }}>
        <span className="cjk t-caption" style={{ color: available ? 'var(--fg-2)' : 'var(--fg-3)' }}>
          {available ? font.label : `${font.label} · 本机未安装`}
        </span>
        {active ? <Lu name="check" size={12} color="var(--accent)" /> : null}
      </div>
    </div>
  );
  return available ? (
    <div onClick={() => onPick(choice)}>{card}</div>
  ) : (
    <Unavailable reason={`本机没有安装 ${font.label}。装上之后这个选项会立刻可用。`}>{card}</Unavailable>
  );
}

